<script>let {release,compact=false}=$props();const size=b=>b?Math.round(b/1024/1024)+' MB':'';const downloads=n=>Number.isInteger(n)&&n>=0?n.toLocaleString():null;</script>
<section class:compact class="release-panel"><div class="release-about"><p class="eyebrow">{release.preview?'PREVIEW RELEASE':'PUBLISHED RELEASE'}</p><h2>{release.name}</h2><p class="hint">Published {new Date(release.date).toLocaleDateString()}</p>{#if downloads(release.mod.download_count)!==null}<p class="download-count" title="GitHub downloads of this version's mod ZIP. Includes repeat downloads; excludes engine downloads."><strong>{downloads(release.mod.download_count)}</strong> mod downloads</p>{/if}</div><div class="site-actions"><a class="tool primary" href={release.mod.browser_download_url}>Download mod{compact?'':' · '+size(release.mod.size)}</a><a class="tool" href={release.engine.browser_download_url}>Required engine{compact?'':' · '+size(release.engine.size)}</a><a class="tool" href="#help">Installation guide</a></div>{#if release.bodycam}<div class="card"><h3>Optional {release.bodycamUpdate?.version||'Bodycam'} engine</h3><p class="hint">DX11-AVX only. Use instead of the standard engine, with both bin and db/mods from the ZIP.</p><a class="tool" href={release.bodycam.browser_download_url}>Download Bodycam engine · {size(release.bodycam.size)}</a>{#if release.bodycamUpdate?.patch}<p class="hint">GAMMA users: also install the matching compatibility patch and follow its included instructions.</p><a class="tool" href={release.bodycamUpdate.patch}>Bodycam GAMMA Patch 1.1.0</a>{/if}</div>{/if}{#if release.stashGrid}<div class="card stash-grid-test"><p class="eyebrow">OPTIONAL · FOR FURTHER TESTING</p><h3>Stash grid test</h3><p>Fixed-size stash grids with a Sort stash button. Player inventory stays manual.</p><p><strong>Empty your stashes before installing.</strong> Install below Squared Away 2.1.0 and its compatibility patches in MO2. Disable older stash grid tests and keep a backup save.</p><p class="hint">Keep your current Squared Away engine. Saving/loading, changing areas and returning, and task-stash loot spawning have been tested by Fomok. Please report any issues in the <a href="https://discord.com/channels/912320241713958912/1542887991222206484">Discord thread</a>.</p><a class="tool" href={release.stashGrid.browser_download_url}>Download optional stash grid test</a></div>{/if}<p class="release-note">Install the mod and its matching engine. Existing 2.0.x saves work with this update.</p>{#if release.tag==='v2.0.5'}<p class="release-note">Keep the 2.0.3 engine. Choose either GAMMA or ZONA compatibility patches. ZONA recipes, repair parts and trader settings may need adaptation from the GAMMA baseline.</p>{/if}{#if release.tag==='v2.0.3'}<p class="release-note">Select the optional Mags Reloaded ammo fix in the FOMOD with Mags Reloaded Fork by Priler UPDATE 6 and its Dynamic Reload Speeds dependency installed. It requires the 2.0.3 engine. Let Squared Away win their file conflicts in MO2.</p>{/if}{#if !compact}<details class="release-notes"><summary>Release notes</summary><div class="release-notes-text">{release.notes}</div></details>{/if}</section>

<style>.download-count{margin:10px 0 0;color:var(--dim);font-size:13px}.download-count strong{color:var(--hot);font-size:16px;font-variant-numeric:tabular-nums}</style>
